-- ============================================================
-- IPISB Platform — RH Phase 16 : Dictionnaire des compétences (comportementales)
-- Run this ONCE in the Supabase SQL Editor.
--
-- Source : « Dictionnaire des compétences » (15 compétences comportementales,
-- chacune avec sa définition et 5 niveaux de maîtrise).
--
--  1. skills.levels : descriptions des niveaux 1 à 5 (text[]).
--  2. employee_skills.level accepte aussi 'level_1' … 'level_5'
--     (les anciennes valeurs beginner/… restent valides).
--  3. Insère les 15 compétences (catégorie soft_skills) ; si une
--     compétence du même nom existe déjà (ex. « Accomplissement »,
--     insensible à la casse) sa définition et ses niveaux sont mis à jour
--     et elle est réactivée — jamais dupliquée.
-- ============================================================

ALTER TABLE skills ADD COLUMN IF NOT EXISTS levels text[];

ALTER TABLE employee_skills DROP CONSTRAINT IF EXISTS employee_skills_level_check;
ALTER TABLE employee_skills
  ADD CONSTRAINT employee_skills_level_check
  CHECK (level IN ('beginner', 'intermediate', 'advanced', 'expert',
                   'level_1', 'level_2', 'level_3', 'level_4', 'level_5'));

-- Compétences déjà présentes : on aligne définition + niveaux sur le dictionnaire.
WITH d(name, description, levels) AS (VALUES
  ($$Accomplissement$$, $$Capacité à orienter ses efforts et ses actes en vue d'atteindre et de dépasser les objectifs, à prendre des risques calculés pour un gain potentiel.$$, ARRAY[$$Cherche à faire correctement son travail. Exprime de la frustration face à l'inefficacité. Fait preuve d'une exigence personnelle limitée : cherche à « faire au mieux » de ses possibilités. S'en remet aux autres en cas de difficulté.$$, $$S'efforce d'atteindre les objectifs et standards de performance fixés (rendement, qualité, délais, budget, marge…) sans chercher particulièrement à les dépasser.$$, $$Cherche à aller au-delà des objectifs et standards existants, s'impose de lui-même des exigences (étapes, contrôles) qui ne sont pas explicitement demandées et qui lui permettent de dépasser la performance attendue. Fixe ses priorités, choisit des méthodes mieux adaptées aux situations pour améliorer son efficacité.$$, $$Cherche en permanence à améliorer les performances individuelles et collectives. Se fixe des objectifs ambitieux, à lui-même ou à son équipe, ainsi que des plans d'actions concrets et détaillés. Améliore les procédés, évalue régulièrement les résultats, en les comparant à ceux des autres (en interne ou face aux standards de l'industrie ou de la concurrence).$$, $$A une attitude d'entrepreneur et est motivé par les défis. Prend des risques calculés après avoir évalué les différentes options. Choisit des objectifs prioritaires à partir d'une analyse coût/efficacité puis alloue les ressources en vue d'une amélioration significative en cohérence avec la stratégie du Groupe.$$]::text[]),
  ($$Adaptabilité$$, $$Capacité à intégrer d'autres points de vue que le sien, à s'adapter aux situations ou à l'environnement, à remettre en cause ses méthodes de travail et ses décisions, à adapter son approche.$$, ARRAY[$$Accepte de changer d'idées ou d'opinion, mais seulement sur la base de nouvelles preuves ou d'évidences contradictoires. Comprend l'intérêt d'autres points de vue que le sien mais sans forcément en tenir compte.$$, $$Comprend l'esprit des règles de fonctionnement du Groupe ONA afin de les appliquer de manière appropriée. Connaît et utilise sa marge de manœuvre. Accepte de modifier ses façons de faire habituelles face à de nouvelles conditions (marché, produits, procédures ...).$$, $$Décide en fonction de la situation. Adapte son comportement dans le cours de l'action face à un fait nouveau. Change d'approche lorsque les circonstances l'exigent. Envisage les problèmes de plusieurs façons. Reste attentif aux évolutions de la situation.$$, $$Change ses plans, l'objectif ou le projet en cours pour mieux s'adapter aux évolutions, tout en gardant les grands objectifs en tête. Peut provoquer un changement important au sein de son entité (société, exploitation, services support,…) pour répondre aux exigences d'une situation.$$, $$Considère les changements comme bénéfiques à son entité ou au Groupe et en est le promoteur. Remet en cause de façon constructive les modes de fonctionnement existants. A titre personnel, accepte un changement de carrière important pour s'adapter à la stratégie de l'entreprise.$$]::text[]),
  ($$Compréhension des organisations$$, $$Capacité à comprendre et utiliser le fonctionnement informel, les circuits de décision et les rapports de pouvoir des organisations dans l'intérêt de l'entreprise : repérer qui influence les décisions et apprécier l'impact d'une décision ou d'un événement sur les personnes et les groupes.$$, ARRAY[$$Au delà de la structure formelle (hiérarchie, transmissions des ordres et informations, procédures standard), comprend la structure informelle : identifie les acteurs clés et les personnes qui ont de l'influence et qui peuvent peser sur une décision. Utilise cette compréhension lorsque la structure formelle ne fonctionne pas parfaitement.$$, $$Comprend la culture et le climat d'une organisation : identifie les limites de l'organisation, ce qu'il est possible de faire à un moment donné, les prérogatives de telle ou telle position, et les contraintes qui limitent son efficacité. Adopte les comportements, le langage qui donnent les meilleurs résultats.$$, $$Comprend, décrypte et utilise les rapports de pouvoir, les alliances. En conséquence, adapte son approche, construit ses plans afin de tirer la plus grande efficacité dans l'intérêt de l'entreprise.$$, $$Comprend en profondeur les raisons des jeux politiques et sociaux : comprend les raisons sous-jacentes des comportements collectifs, des attitudes dans l'organisation ; comprend les enjeux, repère les opportunités et crée sa stratégie en intégrant les conséquences et actions concrètes.$$, $$Intègre sa compréhension des problèmes et des enjeux dans une perspective de long terme, et dans un contexte plus large que celui de l'entreprise. En tire les conséquences effectives dans ses réflexions et décisions stratégiques.$$]::text[]),
  ($$Conceptualisation$$, $$Capacité à évaluer les situations, à mettre en évidence les points clés, à se forger une opinion et à développer une vision des enjeux et des actions à mener.$$, ARRAY[$$Sait traiter des problèmes qui se décomposent en tâches ou activités. Forme son opinion en utilisant des règles simples. Fait des choix entre des situations déjà rencontrées.$$, $$A une approche méthodique des problèmes. Forme son opinion en rassemblant les informations et les faits disponibles, en faisant l'inventaire des avantages et inconvénients de la solution envisagée, et applique le raisonnement analytique pour résoudre les problèmes.$$, $$S'attache à identifier plusieurs aspects d'une situation ou d'un problème et, pour cela, n'hésite pas à consulter d'autres sources d'information pour élargir sa compréhension des faits. Mène une analyse combinant plusieurs critères, envisage plusieurs solutions. Applique le raisonnement logique pour évaluer la situation et la solution puis fait appel au bon sens et à l'intuition pour prendre position.$$, $$Effectue des rapprochements et les synthèses permettant une compréhension élargie des situations, identifie les causes profondes et les conséquences à moyen ou long terme. Fait preuve d'imagination et prend du recul par rapport aux événements.$$, $$Met en œuvre sa créativité au delà de la compréhension globale des situations et de la prise de recul. Puis élabore une vision moyen ou long terme des enjeux et des moyens d'aboutir aux objectifs stratégiques.$$]::text[]),
  ($$Confiance en soi$$, $$Conviction d'avoir la capacité à accomplir un travail, prendre des décisions, surmonter ses échecs, accepter les défis sans craindre d'assumer les conséquences de ses choix. Elle est source d'initiatives, de discussions ou de confrontations fructueuses.$$, ARRAY[$$Exprime son opinion dans son champ de compétences lorsqu'il n'y a ni risque ni opposition. Accepte ses responsabilités en cas d'échec sans toutefois en tirer de leçon.$$, $$Donne son opinion personnelle et fait preuve d'indépendance de jugement. Prend des décisions de manière autonome dans son champ de compétence ou de responsabilité. Montre la capacité d'agir en situations d'incertitude. En cas d'échec, accepte ses responsabilités et en tire une meilleure connaissance de lui-même.$$, $$Affirme sa confiance dans son jugement et ses capacités : défend clairement son point de vue, même face au désaccord afin de « faire bouger les choses ». Tire les leçons de ses échecs en vue de progresser à terme.$$, $$Montre sa confiance en soi dans ses affirmations et dans ses actes : est stimulé par des missions exigeantes. Se manifeste en cas de désaccord avec le management, les clients ou toute autre personne détentrice d'un pouvoir et expose ses vues avec calme et maîtrise mais clairement et avec assurance, même dans un conflit. Reconnaît ouvertement ses erreurs et s'engage formellement sur les améliorations requises.$$, $$Recherche et relève les défis : accepte ou recherche les missions impliquant un risque, ne craint pas d'entrer en conflit avec des supérieurs ou des clients si l'enjeu porte sur son activité ou celle de l'entreprise.$$]::text[]),
  ($$Coopération$$, $$Volonté et capacité à travailler avec d'autres au sein d'une équipe (ou d'un projet transversal dans l'entreprise n'impliquant pas nécessairement de liens hiérarchiques) afin d'atteindre un objectif commun – plutôt que de travailler seul ou en compétition avec les autres.$$, ARRAY[$$Suit les décisions concernant l'équipe et réalise sa part du travail. En tant que membre de l'équipe, tient les autres membres informés et au courant de ce qui lui semble nécessaire pour qu'ils réalisent leur travail. Montre de l'implication dans son rôle.$$, $$A une vision élargie de son rôle, montre de l'intérêt pour les besoins globaux de l'organisation. Fait des choix et fixe des priorités en prenant en compte les besoins collectifs. A une attitude positive vis-à-vis des autres membres de l'équipe, quant à leurs contributions et leurs capacités. Contribue à l'efficacité du travail en équipe en offrant aide et assistance aux autres.$$, $$Fait preuve d'une attitude proactive, participe à des actions au delà des attributions de son rôle afin de contribuer à des objectifs collectifs. Reconnaît sincèrement la valeur de l'apport de chacun, encourage la participation des membres de groupes de travail à l'atteinte des objectifs définis. Se sent solidaire des autres et leur fait partager ce sentiment.$$, $$Prend une part active à des projets transversaux dans l'organisation en dehors de son entité. Encourage les membres des équipes transversales à travailler vers un but commun. Reconnaît publiquement les succès des autres, leur donne confiance dans leurs capacités. Indique son respect à l'égard des membres de l'équipe en tenant ses engagements.$$, $$Prend des initiatives de travail en mode transversal, qui privilégient le progrès de l'entreprise. S'engage personnellement dans des actions collectives. Promeut les travaux et l'image de l'équipe par ailleurs au sein du Groupe.$$]::text[]),
  ($$Développement des autres$$, $$Volonté de faire progresser professionnellement ses collaborateurs (ou collègues) sur le long terme, par une appréciation de leurs forces et limites, et en leur fournissant les moyens de développement appropriés.$$, ARRAY[$$Explique comment faire dans des situations de travail, en fait la démonstration, donne des conseils utiles. Fait le constat avec ses collaborateurs des résultats obtenus sans toutefois chercher à en tirer des enseignements particuliers.$$, $$Donne des explications sur le « comment faire » mais aussi sur le « pour quoi faire ». Fait preuve de pédagogie en s'assurant que les explications sont bien perçues et comprises. Offre son assistance pour faciliter le travail de ses collaborateurs ou collègues. Fournit à ses collaborateurs des appréciations factuelles sur leurs résultats.$$, $$Donne une appréciation en retour, de manière positive et précise, dans le but de faire progresser. Redonne de l'assurance aux autres après un échec, en donnant une appréciation constructive mais sans complaisance. Se montre disponible pour les aider dans les situations difficiles et leur procurer les informations nécessaires.$$, $$Exploite les situations de travail dans l'optique du développement continu de ses collaborateurs. Après avoir évalué leur compétence, favorise leur autonomie en leur déléguant la responsabilité nécessaire et en les amenant à trouver par eux-mêmes la réponse aux problèmes rencontrés pour qu'ils accomplissent leur mission. Accepte le droit à l'erreur comme source d'apprentissage.$$, $$Tient un langage clair à ses collaborateurs sur leurs évolutions possibles au sein du Groupe et prépare le développement de carrière de ceux dont il a identifié le potentiel. Favorise la mobilité en acceptant que ses meilleurs éléments quittent son équipe. Anticipe les remplacements que ces mouvements impliquent, y compris la préparation de sa propre succession.$$]::text[]),
  ($$Partage d'expertise$$, $$Capacité à actualiser et développer ses connaissances pour lui-même et propension à les diffuser et à les faire s'approprier par les autres.$$, ARRAY[$$Répond volontiers aux questions de ceux qui le consultent en tant que professionnel dans son domaine. Entretient une communication claire : donne les informations utiles, entretient les relations nécessaires à une bonne compréhension des attentes mutuelles, s'assure que ses réponses apportent satisfaction.$$, $$Fournit spontanément soutien et assistance : va au delà d'une simple réponse à une question et fournit l'information complémentaire permettant une meilleure compréhension d'un aspect technique ou d'un problème. Passe du temps à aider les autres pour résoudre leurs difficultés techniques.$$, $$Diffuse son savoir auprès des autres, les sollicite pour recueillir des idées en vue d'améliorer la qualité de ses réponses. S'efforce concrètement de donner une valeur ajoutée à son interlocuteur, se rend disponible lorsqu'il se trouve en difficulté. Se rend joignable en permanence si la situation est critique ou difficile. Contribue aux actions de formation.$$, $$Met son expertise au service des autres, à son initiative, leur propose son aide pour améliorer les performances. Prend en compte les besoins sous-jacents : recherche activement à connaître les besoins réels de ses interlocuteurs au-delà de la demande initiale, et les prend en compte pour rechercher, appliquer ou adapter une solution.$$, $$Fait évoluer les méthodes du Groupe et fait partager à l'ensemble des collaborateurs d'une fonction sa vision prospective (métier, finance…). Promeut des techniques nouvelles dans l'entreprise, agit comme agent de changement dans son domaine d'expertise. Prend des initiatives et exploite des opportunités pour faire partager de nouvelles connaissances et développer le savoir-faire de l'entreprise. Est reconnu comme une autorité, dans un domaine professionnel particulièrement complexe. Agit en conseiller écouté et influent de ses interlocuteurs.$$]::text[]),
  ($$Impact & Communication$$, $$Capacité à adapter ses messages à ses interlocuteurs, à les convaincre et les amener à ce que l'on souhaite, dans l'intérêt du Groupe.$$, ARRAY[$$Convainc en utilisant essentiellement des arguments rationnels et afin de souligner les avantages de ses propositions, se sert d'exemples courants, sans préparation spécifique, ni adaptation de son langage.$$, $$Cherche à convaincre en préparant son discours et ses interventions, ou présentations avec des arguments logiques et construits. Prépare une argumentation solide et de qualité, utilise des exemples concrets et fait appel au raisonnement et au bon sens des autres.$$, $$Anticipe l'effet de ses actes et de ses paroles sur les autres, et mesure l'impact de ses actions : adapte son exposé, ses arguments en fonction des intérêts et des attentes des autres. Anticipe les réactions et prépare des réponses adaptées afin de renforcer l'effet escompté.$$, $$Cherche à avoir un impact marquant sur les autres, prépare ses actions de manière à surprendre, à impressionner ou même à déstabiliser. Mène des actions d'influence en plusieurs étapes, chacune étant adaptée à un public et à un contexte donnés.$$, $$Construit une stratégie d'influence pour emporter l'adhésion : combine plusieurs moyens d'impact, se sert d'arguments multiples, d'avis d'experts, d'appuis ou d'alliances. Utilise sa connaissance de ses interlocuteurs et du fonctionnement des organisations pour déterminer la stratégie la plus efficace.$$]::text[]),
  ($$Initiative$$, $$Capacité à identifier les opportunités futures (ou obstacles) et à agir dès maintenant de manière à en tirer avantage (ou les contrer).$$, ARRAY[$$Agit en fonction des problèmes ou des opportunités immédiates, et en utilisant des solutions standards.$$, $$Agit spontanément dans les situations de crise, où les autres ont l'habitude de temporiser et d'espérer que le problème se résoudra tout seul. Néanmoins, ne cherche pas à s'assurer que la solution est pertinente à moyen terme ou qu'elle induit des effets adverses.$$, $$Saisit ou crée des opportunités ou prévient des problèmes, en engageant une action spécifique (nouveau programme, modification d'une procédure existante…), à un horizon court à moyen terme.$$, $$Anticipe et se prépare en vue d'une opportunité ou d'une difficulté qui ne sont pas évidentes pour les autres (évolution des marchés, de la technologie…). N'attend pas que ses interlocuteurs lui présentent un problème pour lancer une réflexion sur un sujet. Agit en vue du moyen terme.$$, $$Anticipe à long terme les évolutions dans l'environnement externe et engage des actions pour lancer de nouveaux produits, services ou stratégies - afin de tirer profit des opportunités et avec un impact majeur sur l'activité de l'entreprise.$$]::text[]),
  ($$Leadership$$, $$Capacité à entraîner ses collaborateurs vers des résultats ambitieux, en leur communiquant vision et objectifs et en mettant en place une organisation et des moyens, et en fournissant son support personnel.$$, ARRAY[$$Donne les instructions, communique la mission et les objectifs, définit l'agenda, contrôle les échéances, affecte les tâches… Communique les raisons d'une décision en s'en tenant à la seule explication.$$, $$Fournit les règles du jeu, les objectifs (production, qualité, délais, …) et les explicite. Indique comment les atteindre. Exprime ses exigences en matière de professionnalisme. Analyse la performance de l'équipe et en fait le retour collectif.$$, $$Montre son engagement et son soutien à l'équipe, en promeut la réputation au sein de la société et du Groupe. S'assure que ses besoins pratiques sont satisfaits (en personnel, ressources, informations…) en donnant le support nécessaire. Établit et communique les normes de performance de l'équipe en les plaçant dans le contexte de l'entreprise et dans une perspective moyen terme.$$, $$Développe une dynamique d'équipe, au sein de laquelle chacun reconnaît le rôle et les compétences des autres. Sollicite les suggestions et critiques, accepte la confrontation quand elle amène un progrès. Développe le goût du challenge et de la réussite.$$, $$Communique une vision ambitieuse à son équipe, qui génère excitation, enthousiasme et engagement. « Fait acheter » par les autres les projets. Promeut les standards de performance et les objectifs. S'assure qu'ils sont atteints. Fixe les normes de comportements requis des collaborateurs en étant lui-même exemplaire.$$]::text[]),
  ($$Orientation service clients$$, $$Volonté de concentrer son action sur la découverte et la compréhension des besoins des personnes auxquelles un service est rendu (client interne ou externe) et de les satisfaire afin d'établir dans la durée une relation de qualité.$$, ARRAY[$$Répond aux demandes du client, assure un suivi de la relation, fournit toutes les informations utiles. Entretient une communication claire, s'assure de la bonne compréhension des attentes mutuelles et de la satisfaction du client sans toutefois aller au-delà de la demande.$$, $$Est à l'écoute du client, maintient le contact, s'intéresse à ses besoins et s'assure que sa demande est traitée efficacement. Contrôle sa satisfaction et se rend totalement disponible, notamment quand son client est en difficulté, n'hésite pas à investir le temps et les efforts nécessaires pour son client si la situation est critique.$$, $$Se considère personnellement responsable de la qualité de la prestation fournie, agit pour offrir une meilleure qualité de service : identifie et analyse l'ensemble des besoins exprimés par le client. Prend les mesures nécessaires pour corriger les défaillances éventuelles. Évalue en permanence le niveau de satisfaction de ses clients et cherche systématiquement à accroître la valeur de sa prestation, de faire mieux d'une façon ou d'une autre.$$, $$Recherche les besoins véritables du client, au-delà de sa demande, en vue d'y apporter une solution adaptée. Fait tout ce qui lui est possible pour répondre à ces besoins, par ses propres actions et en impliquant les autres. Lorsqu'il découvre un besoin non exprimé, propose une action correctrice à sa hiérarchie.$$, $$Agit en conseiller de confiance en offrant une vue objective à ses clients. Agit dans l'optique d'une relation durable et mutuellement profitable à long terme (fidélisation, partenariat) : recommande des approches nouvelles, différentes de celles imaginées par le client lui-même. Est à même d'arbitrer en faveur du long terme en renonçant si nécessaire à des profits immédiats.$$]::text[]),
  ($$Recherche d'informations$$, $$Propension à rechercher des données et des informations sur les choses, les situations ou les personnes. Capacité à détecter ce qui peut être utile dans le futur au delà de la demande du moment.$$, ARRAY[$$Recueille et utilise les informations sans nécessairement en approfondir la provenance ou l'exactitude.$$, $$Recherche à l'avance les informations nécessaires pour prendre une position ou une décision. Cherche à approfondir la pertinence des informations obtenues en posant des questions complémentaires sur leurs sources et leur fiabilité.$$, $$Recherche d'autres points de vue que le sien et sollicite des tiers qui ne sont pas directement impliqués. Compare ses informations et méthodes de travail à celles de ses pairs, au sein du Groupe.$$, $$Procède à des enquêtes ou supervise une recherche d'information structurée. Recherche des éléments auprès de sources inhabituelles (experts d'un domaine…). Effectue des comparaisons avec les professionnels de son domaine, à l'échelle nationale ou internationale.$$, $$Construit et met en place ses propres systèmes de recherche et circuits pour obtenir de l'information. Suscite auprès de ses collaborateurs une démarche de recherche active d'informations à l'égard des pratiques du domaine professionnel.$$]::text[]),
  ($$Empathie relationnelle$$, $$Capacité à percevoir et comprendre ce que les autres pensent ou ressentent, au-delà de ce qu'ils expriment.$$, ARRAY[$$Comprend les paroles et les émotions manifestées directement par les personnes.$$, $$Saisit les paroles et les émotions au delà de ce qui est exprimé et du contenu explicite. Interprète les messages, tient compte de l'émotion et du ressenti manifestés : les pensées, les préoccupations, les sentiments, dans la situation présente.$$, $$Perçoit le contenu implicite et les raisons du comportement des autres : comprend les problèmes sous-jacents d'autrui, les causes de ses difficultés ou problèmes, est capable d'une évaluation pondérée de leurs qualités et de leurs limites.$$, $$Ressent les causes profondes et complexes des comportements des autres et les met en relation avec leurs problèmes personnels, leurs contextes professionnels et extra-professionnels.$$, $$Intègre les comportements des autres dans le cadre des enjeux politiques de l'entreprise à moyen ou long terme. Met à profit sa compréhension profonde de ses interlocuteurs afin de construire les stratégies d'impact les plus efficaces.$$]::text[]),
  ($$Rigueur$$, $$La rigueur reflète le souci constant de réduire l'incertitude, de préciser les rôles et les responsabilités, de vérifier l'exactitude des données et des résultats.$$, ARRAY[$$Vérifie l'exactitude des données qu'il utilise. Vérifie son travail avant de le remettre. Tient un classement des informations qui lui sont utiles.$$, $$Vérifie les choses, croise les résultats avec d'autres sources pour s'assurer de leur exactitude. S'assure de la qualité du travail des autres. S'assure que le travail fourni est conforme aux attentes.$$, $$S'assure que les résultats produits par lui-même ou les autres respectent les normes de la société ou du Groupe ONA, que les procédures sont respectées et que les informations utiles sont enregistrées. Veille aux détails des projets ainsi qu'à leur état d'avancement.$$, $$Encourage les membres d'une équipe à s'assurer mutuellement de la qualité de leur travail. Fait valider ses conclusions devant un groupe de travail avant de les considérer comme acquises. Met en place des processus améliorant la qualité et la fiabilité de ses travaux ainsi que ceux de ses collaborateurs.$$, $$Se sent personnellement responsable de la qualité dans tous ses aspects : prestations, coûts, délais, et climat de travail. Dirige des actions de conception et de mise en place de systèmes visant à accroître la fiabilité et la qualité des informations reçues et des résultats produits.$$]::text[])
)
UPDATE skills s
SET description = d.description, levels = d.levels, is_active = true
FROM d
WHERE lower(trim(s.name)) = lower(trim(d.name));

-- Compétences manquantes : on les crée.
WITH d(name, description, levels) AS (VALUES
  ($$Accomplissement$$, $$Capacité à orienter ses efforts et ses actes en vue d'atteindre et de dépasser les objectifs, à prendre des risques calculés pour un gain potentiel.$$, ARRAY[$$Cherche à faire correctement son travail. Exprime de la frustration face à l'inefficacité. Fait preuve d'une exigence personnelle limitée : cherche à « faire au mieux » de ses possibilités. S'en remet aux autres en cas de difficulté.$$, $$S'efforce d'atteindre les objectifs et standards de performance fixés (rendement, qualité, délais, budget, marge…) sans chercher particulièrement à les dépasser.$$, $$Cherche à aller au-delà des objectifs et standards existants, s'impose de lui-même des exigences (étapes, contrôles) qui ne sont pas explicitement demandées et qui lui permettent de dépasser la performance attendue. Fixe ses priorités, choisit des méthodes mieux adaptées aux situations pour améliorer son efficacité.$$, $$Cherche en permanence à améliorer les performances individuelles et collectives. Se fixe des objectifs ambitieux, à lui-même ou à son équipe, ainsi que des plans d'actions concrets et détaillés. Améliore les procédés, évalue régulièrement les résultats, en les comparant à ceux des autres (en interne ou face aux standards de l'industrie ou de la concurrence).$$, $$A une attitude d'entrepreneur et est motivé par les défis. Prend des risques calculés après avoir évalué les différentes options. Choisit des objectifs prioritaires à partir d'une analyse coût/efficacité puis alloue les ressources en vue d'une amélioration significative en cohérence avec la stratégie du Groupe.$$]::text[]),
  ($$Adaptabilité$$, $$Capacité à intégrer d'autres points de vue que le sien, à s'adapter aux situations ou à l'environnement, à remettre en cause ses méthodes de travail et ses décisions, à adapter son approche.$$, ARRAY[$$Accepte de changer d'idées ou d'opinion, mais seulement sur la base de nouvelles preuves ou d'évidences contradictoires. Comprend l'intérêt d'autres points de vue que le sien mais sans forcément en tenir compte.$$, $$Comprend l'esprit des règles de fonctionnement du Groupe ONA afin de les appliquer de manière appropriée. Connaît et utilise sa marge de manœuvre. Accepte de modifier ses façons de faire habituelles face à de nouvelles conditions (marché, produits, procédures ...).$$, $$Décide en fonction de la situation. Adapte son comportement dans le cours de l'action face à un fait nouveau. Change d'approche lorsque les circonstances l'exigent. Envisage les problèmes de plusieurs façons. Reste attentif aux évolutions de la situation.$$, $$Change ses plans, l'objectif ou le projet en cours pour mieux s'adapter aux évolutions, tout en gardant les grands objectifs en tête. Peut provoquer un changement important au sein de son entité (société, exploitation, services support,…) pour répondre aux exigences d'une situation.$$, $$Considère les changements comme bénéfiques à son entité ou au Groupe et en est le promoteur. Remet en cause de façon constructive les modes de fonctionnement existants. A titre personnel, accepte un changement de carrière important pour s'adapter à la stratégie de l'entreprise.$$]::text[]),
  ($$Compréhension des organisations$$, $$Capacité à comprendre et utiliser le fonctionnement informel, les circuits de décision et les rapports de pouvoir des organisations dans l'intérêt de l'entreprise : repérer qui influence les décisions et apprécier l'impact d'une décision ou d'un événement sur les personnes et les groupes.$$, ARRAY[$$Au delà de la structure formelle (hiérarchie, transmissions des ordres et informations, procédures standard), comprend la structure informelle : identifie les acteurs clés et les personnes qui ont de l'influence et qui peuvent peser sur une décision. Utilise cette compréhension lorsque la structure formelle ne fonctionne pas parfaitement.$$, $$Comprend la culture et le climat d'une organisation : identifie les limites de l'organisation, ce qu'il est possible de faire à un moment donné, les prérogatives de telle ou telle position, et les contraintes qui limitent son efficacité. Adopte les comportements, le langage qui donnent les meilleurs résultats.$$, $$Comprend, décrypte et utilise les rapports de pouvoir, les alliances. En conséquence, adapte son approche, construit ses plans afin de tirer la plus grande efficacité dans l'intérêt de l'entreprise.$$, $$Comprend en profondeur les raisons des jeux politiques et sociaux : comprend les raisons sous-jacentes des comportements collectifs, des attitudes dans l'organisation ; comprend les enjeux, repère les opportunités et crée sa stratégie en intégrant les conséquences et actions concrètes.$$, $$Intègre sa compréhension des problèmes et des enjeux dans une perspective de long terme, et dans un contexte plus large que celui de l'entreprise. En tire les conséquences effectives dans ses réflexions et décisions stratégiques.$$]::text[]),
  ($$Conceptualisation$$, $$Capacité à évaluer les situations, à mettre en évidence les points clés, à se forger une opinion et à développer une vision des enjeux et des actions à mener.$$, ARRAY[$$Sait traiter des problèmes qui se décomposent en tâches ou activités. Forme son opinion en utilisant des règles simples. Fait des choix entre des situations déjà rencontrées.$$, $$A une approche méthodique des problèmes. Forme son opinion en rassemblant les informations et les faits disponibles, en faisant l'inventaire des avantages et inconvénients de la solution envisagée, et applique le raisonnement analytique pour résoudre les problèmes.$$, $$S'attache à identifier plusieurs aspects d'une situation ou d'un problème et, pour cela, n'hésite pas à consulter d'autres sources d'information pour élargir sa compréhension des faits. Mène une analyse combinant plusieurs critères, envisage plusieurs solutions. Applique le raisonnement logique pour évaluer la situation et la solution puis fait appel au bon sens et à l'intuition pour prendre position.$$, $$Effectue des rapprochements et les synthèses permettant une compréhension élargie des situations, identifie les causes profondes et les conséquences à moyen ou long terme. Fait preuve d'imagination et prend du recul par rapport aux événements.$$, $$Met en œuvre sa créativité au delà de la compréhension globale des situations et de la prise de recul. Puis élabore une vision moyen ou long terme des enjeux et des moyens d'aboutir aux objectifs stratégiques.$$]::text[]),
  ($$Confiance en soi$$, $$Conviction d'avoir la capacité à accomplir un travail, prendre des décisions, surmonter ses échecs, accepter les défis sans craindre d'assumer les conséquences de ses choix. Elle est source d'initiatives, de discussions ou de confrontations fructueuses.$$, ARRAY[$$Exprime son opinion dans son champ de compétences lorsqu'il n'y a ni risque ni opposition. Accepte ses responsabilités en cas d'échec sans toutefois en tirer de leçon.$$, $$Donne son opinion personnelle et fait preuve d'indépendance de jugement. Prend des décisions de manière autonome dans son champ de compétence ou de responsabilité. Montre la capacité d'agir en situations d'incertitude. En cas d'échec, accepte ses responsabilités et en tire une meilleure connaissance de lui-même.$$, $$Affirme sa confiance dans son jugement et ses capacités : défend clairement son point de vue, même face au désaccord afin de « faire bouger les choses ». Tire les leçons de ses échecs en vue de progresser à terme.$$, $$Montre sa confiance en soi dans ses affirmations et dans ses actes : est stimulé par des missions exigeantes. Se manifeste en cas de désaccord avec le management, les clients ou toute autre personne détentrice d'un pouvoir et expose ses vues avec calme et maîtrise mais clairement et avec assurance, même dans un conflit. Reconnaît ouvertement ses erreurs et s'engage formellement sur les améliorations requises.$$, $$Recherche et relève les défis : accepte ou recherche les missions impliquant un risque, ne craint pas d'entrer en conflit avec des supérieurs ou des clients si l'enjeu porte sur son activité ou celle de l'entreprise.$$]::text[]),
  ($$Coopération$$, $$Volonté et capacité à travailler avec d'autres au sein d'une équipe (ou d'un projet transversal dans l'entreprise n'impliquant pas nécessairement de liens hiérarchiques) afin d'atteindre un objectif commun – plutôt que de travailler seul ou en compétition avec les autres.$$, ARRAY[$$Suit les décisions concernant l'équipe et réalise sa part du travail. En tant que membre de l'équipe, tient les autres membres informés et au courant de ce qui lui semble nécessaire pour qu'ils réalisent leur travail. Montre de l'implication dans son rôle.$$, $$A une vision élargie de son rôle, montre de l'intérêt pour les besoins globaux de l'organisation. Fait des choix et fixe des priorités en prenant en compte les besoins collectifs. A une attitude positive vis-à-vis des autres membres de l'équipe, quant à leurs contributions et leurs capacités. Contribue à l'efficacité du travail en équipe en offrant aide et assistance aux autres.$$, $$Fait preuve d'une attitude proactive, participe à des actions au delà des attributions de son rôle afin de contribuer à des objectifs collectifs. Reconnaît sincèrement la valeur de l'apport de chacun, encourage la participation des membres de groupes de travail à l'atteinte des objectifs définis. Se sent solidaire des autres et leur fait partager ce sentiment.$$, $$Prend une part active à des projets transversaux dans l'organisation en dehors de son entité. Encourage les membres des équipes transversales à travailler vers un but commun. Reconnaît publiquement les succès des autres, leur donne confiance dans leurs capacités. Indique son respect à l'égard des membres de l'équipe en tenant ses engagements.$$, $$Prend des initiatives de travail en mode transversal, qui privilégient le progrès de l'entreprise. S'engage personnellement dans des actions collectives. Promeut les travaux et l'image de l'équipe par ailleurs au sein du Groupe.$$]::text[]),
  ($$Développement des autres$$, $$Volonté de faire progresser professionnellement ses collaborateurs (ou collègues) sur le long terme, par une appréciation de leurs forces et limites, et en leur fournissant les moyens de développement appropriés.$$, ARRAY[$$Explique comment faire dans des situations de travail, en fait la démonstration, donne des conseils utiles. Fait le constat avec ses collaborateurs des résultats obtenus sans toutefois chercher à en tirer des enseignements particuliers.$$, $$Donne des explications sur le « comment faire » mais aussi sur le « pour quoi faire ». Fait preuve de pédagogie en s'assurant que les explications sont bien perçues et comprises. Offre son assistance pour faciliter le travail de ses collaborateurs ou collègues. Fournit à ses collaborateurs des appréciations factuelles sur leurs résultats.$$, $$Donne une appréciation en retour, de manière positive et précise, dans le but de faire progresser. Redonne de l'assurance aux autres après un échec, en donnant une appréciation constructive mais sans complaisance. Se montre disponible pour les aider dans les situations difficiles et leur procurer les informations nécessaires.$$, $$Exploite les situations de travail dans l'optique du développement continu de ses collaborateurs. Après avoir évalué leur compétence, favorise leur autonomie en leur déléguant la responsabilité nécessaire et en les amenant à trouver par eux-mêmes la réponse aux problèmes rencontrés pour qu'ils accomplissent leur mission. Accepte le droit à l'erreur comme source d'apprentissage.$$, $$Tient un langage clair à ses collaborateurs sur leurs évolutions possibles au sein du Groupe et prépare le développement de carrière de ceux dont il a identifié le potentiel. Favorise la mobilité en acceptant que ses meilleurs éléments quittent son équipe. Anticipe les remplacements que ces mouvements impliquent, y compris la préparation de sa propre succession.$$]::text[]),
  ($$Partage d'expertise$$, $$Capacité à actualiser et développer ses connaissances pour lui-même et propension à les diffuser et à les faire s'approprier par les autres.$$, ARRAY[$$Répond volontiers aux questions de ceux qui le consultent en tant que professionnel dans son domaine. Entretient une communication claire : donne les informations utiles, entretient les relations nécessaires à une bonne compréhension des attentes mutuelles, s'assure que ses réponses apportent satisfaction.$$, $$Fournit spontanément soutien et assistance : va au delà d'une simple réponse à une question et fournit l'information complémentaire permettant une meilleure compréhension d'un aspect technique ou d'un problème. Passe du temps à aider les autres pour résoudre leurs difficultés techniques.$$, $$Diffuse son savoir auprès des autres, les sollicite pour recueillir des idées en vue d'améliorer la qualité de ses réponses. S'efforce concrètement de donner une valeur ajoutée à son interlocuteur, se rend disponible lorsqu'il se trouve en difficulté. Se rend joignable en permanence si la situation est critique ou difficile. Contribue aux actions de formation.$$, $$Met son expertise au service des autres, à son initiative, leur propose son aide pour améliorer les performances. Prend en compte les besoins sous-jacents : recherche activement à connaître les besoins réels de ses interlocuteurs au-delà de la demande initiale, et les prend en compte pour rechercher, appliquer ou adapter une solution.$$, $$Fait évoluer les méthodes du Groupe et fait partager à l'ensemble des collaborateurs d'une fonction sa vision prospective (métier, finance…). Promeut des techniques nouvelles dans l'entreprise, agit comme agent de changement dans son domaine d'expertise. Prend des initiatives et exploite des opportunités pour faire partager de nouvelles connaissances et développer le savoir-faire de l'entreprise. Est reconnu comme une autorité, dans un domaine professionnel particulièrement complexe. Agit en conseiller écouté et influent de ses interlocuteurs.$$]::text[]),
  ($$Impact & Communication$$, $$Capacité à adapter ses messages à ses interlocuteurs, à les convaincre et les amener à ce que l'on souhaite, dans l'intérêt du Groupe.$$, ARRAY[$$Convainc en utilisant essentiellement des arguments rationnels et afin de souligner les avantages de ses propositions, se sert d'exemples courants, sans préparation spécifique, ni adaptation de son langage.$$, $$Cherche à convaincre en préparant son discours et ses interventions, ou présentations avec des arguments logiques et construits. Prépare une argumentation solide et de qualité, utilise des exemples concrets et fait appel au raisonnement et au bon sens des autres.$$, $$Anticipe l'effet de ses actes et de ses paroles sur les autres, et mesure l'impact de ses actions : adapte son exposé, ses arguments en fonction des intérêts et des attentes des autres. Anticipe les réactions et prépare des réponses adaptées afin de renforcer l'effet escompté.$$, $$Cherche à avoir un impact marquant sur les autres, prépare ses actions de manière à surprendre, à impressionner ou même à déstabiliser. Mène des actions d'influence en plusieurs étapes, chacune étant adaptée à un public et à un contexte donnés.$$, $$Construit une stratégie d'influence pour emporter l'adhésion : combine plusieurs moyens d'impact, se sert d'arguments multiples, d'avis d'experts, d'appuis ou d'alliances. Utilise sa connaissance de ses interlocuteurs et du fonctionnement des organisations pour déterminer la stratégie la plus efficace.$$]::text[]),
  ($$Initiative$$, $$Capacité à identifier les opportunités futures (ou obstacles) et à agir dès maintenant de manière à en tirer avantage (ou les contrer).$$, ARRAY[$$Agit en fonction des problèmes ou des opportunités immédiates, et en utilisant des solutions standards.$$, $$Agit spontanément dans les situations de crise, où les autres ont l'habitude de temporiser et d'espérer que le problème se résoudra tout seul. Néanmoins, ne cherche pas à s'assurer que la solution est pertinente à moyen terme ou qu'elle induit des effets adverses.$$, $$Saisit ou crée des opportunités ou prévient des problèmes, en engageant une action spécifique (nouveau programme, modification d'une procédure existante…), à un horizon court à moyen terme.$$, $$Anticipe et se prépare en vue d'une opportunité ou d'une difficulté qui ne sont pas évidentes pour les autres (évolution des marchés, de la technologie…). N'attend pas que ses interlocuteurs lui présentent un problème pour lancer une réflexion sur un sujet. Agit en vue du moyen terme.$$, $$Anticipe à long terme les évolutions dans l'environnement externe et engage des actions pour lancer de nouveaux produits, services ou stratégies - afin de tirer profit des opportunités et avec un impact majeur sur l'activité de l'entreprise.$$]::text[]),
  ($$Leadership$$, $$Capacité à entraîner ses collaborateurs vers des résultats ambitieux, en leur communiquant vision et objectifs et en mettant en place une organisation et des moyens, et en fournissant son support personnel.$$, ARRAY[$$Donne les instructions, communique la mission et les objectifs, définit l'agenda, contrôle les échéances, affecte les tâches… Communique les raisons d'une décision en s'en tenant à la seule explication.$$, $$Fournit les règles du jeu, les objectifs (production, qualité, délais, …) et les explicite. Indique comment les atteindre. Exprime ses exigences en matière de professionnalisme. Analyse la performance de l'équipe et en fait le retour collectif.$$, $$Montre son engagement et son soutien à l'équipe, en promeut la réputation au sein de la société et du Groupe. S'assure que ses besoins pratiques sont satisfaits (en personnel, ressources, informations…) en donnant le support nécessaire. Établit et communique les normes de performance de l'équipe en les plaçant dans le contexte de l'entreprise et dans une perspective moyen terme.$$, $$Développe une dynamique d'équipe, au sein de laquelle chacun reconnaît le rôle et les compétences des autres. Sollicite les suggestions et critiques, accepte la confrontation quand elle amène un progrès. Développe le goût du challenge et de la réussite.$$, $$Communique une vision ambitieuse à son équipe, qui génère excitation, enthousiasme et engagement. « Fait acheter » par les autres les projets. Promeut les standards de performance et les objectifs. S'assure qu'ils sont atteints. Fixe les normes de comportements requis des collaborateurs en étant lui-même exemplaire.$$]::text[]),
  ($$Orientation service clients$$, $$Volonté de concentrer son action sur la découverte et la compréhension des besoins des personnes auxquelles un service est rendu (client interne ou externe) et de les satisfaire afin d'établir dans la durée une relation de qualité.$$, ARRAY[$$Répond aux demandes du client, assure un suivi de la relation, fournit toutes les informations utiles. Entretient une communication claire, s'assure de la bonne compréhension des attentes mutuelles et de la satisfaction du client sans toutefois aller au-delà de la demande.$$, $$Est à l'écoute du client, maintient le contact, s'intéresse à ses besoins et s'assure que sa demande est traitée efficacement. Contrôle sa satisfaction et se rend totalement disponible, notamment quand son client est en difficulté, n'hésite pas à investir le temps et les efforts nécessaires pour son client si la situation est critique.$$, $$Se considère personnellement responsable de la qualité de la prestation fournie, agit pour offrir une meilleure qualité de service : identifie et analyse l'ensemble des besoins exprimés par le client. Prend les mesures nécessaires pour corriger les défaillances éventuelles. Évalue en permanence le niveau de satisfaction de ses clients et cherche systématiquement à accroître la valeur de sa prestation, de faire mieux d'une façon ou d'une autre.$$, $$Recherche les besoins véritables du client, au-delà de sa demande, en vue d'y apporter une solution adaptée. Fait tout ce qui lui est possible pour répondre à ces besoins, par ses propres actions et en impliquant les autres. Lorsqu'il découvre un besoin non exprimé, propose une action correctrice à sa hiérarchie.$$, $$Agit en conseiller de confiance en offrant une vue objective à ses clients. Agit dans l'optique d'une relation durable et mutuellement profitable à long terme (fidélisation, partenariat) : recommande des approches nouvelles, différentes de celles imaginées par le client lui-même. Est à même d'arbitrer en faveur du long terme en renonçant si nécessaire à des profits immédiats.$$]::text[]),
  ($$Recherche d'informations$$, $$Propension à rechercher des données et des informations sur les choses, les situations ou les personnes. Capacité à détecter ce qui peut être utile dans le futur au delà de la demande du moment.$$, ARRAY[$$Recueille et utilise les informations sans nécessairement en approfondir la provenance ou l'exactitude.$$, $$Recherche à l'avance les informations nécessaires pour prendre une position ou une décision. Cherche à approfondir la pertinence des informations obtenues en posant des questions complémentaires sur leurs sources et leur fiabilité.$$, $$Recherche d'autres points de vue que le sien et sollicite des tiers qui ne sont pas directement impliqués. Compare ses informations et méthodes de travail à celles de ses pairs, au sein du Groupe.$$, $$Procède à des enquêtes ou supervise une recherche d'information structurée. Recherche des éléments auprès de sources inhabituelles (experts d'un domaine…). Effectue des comparaisons avec les professionnels de son domaine, à l'échelle nationale ou internationale.$$, $$Construit et met en place ses propres systèmes de recherche et circuits pour obtenir de l'information. Suscite auprès de ses collaborateurs une démarche de recherche active d'informations à l'égard des pratiques du domaine professionnel.$$]::text[]),
  ($$Empathie relationnelle$$, $$Capacité à percevoir et comprendre ce que les autres pensent ou ressentent, au-delà de ce qu'ils expriment.$$, ARRAY[$$Comprend les paroles et les émotions manifestées directement par les personnes.$$, $$Saisit les paroles et les émotions au delà de ce qui est exprimé et du contenu explicite. Interprète les messages, tient compte de l'émotion et du ressenti manifestés : les pensées, les préoccupations, les sentiments, dans la situation présente.$$, $$Perçoit le contenu implicite et les raisons du comportement des autres : comprend les problèmes sous-jacents d'autrui, les causes de ses difficultés ou problèmes, est capable d'une évaluation pondérée de leurs qualités et de leurs limites.$$, $$Ressent les causes profondes et complexes des comportements des autres et les met en relation avec leurs problèmes personnels, leurs contextes professionnels et extra-professionnels.$$, $$Intègre les comportements des autres dans le cadre des enjeux politiques de l'entreprise à moyen ou long terme. Met à profit sa compréhension profonde de ses interlocuteurs afin de construire les stratégies d'impact les plus efficaces.$$]::text[]),
  ($$Rigueur$$, $$La rigueur reflète le souci constant de réduire l'incertitude, de préciser les rôles et les responsabilités, de vérifier l'exactitude des données et des résultats.$$, ARRAY[$$Vérifie l'exactitude des données qu'il utilise. Vérifie son travail avant de le remettre. Tient un classement des informations qui lui sont utiles.$$, $$Vérifie les choses, croise les résultats avec d'autres sources pour s'assurer de leur exactitude. S'assure de la qualité du travail des autres. S'assure que le travail fourni est conforme aux attentes.$$, $$S'assure que les résultats produits par lui-même ou les autres respectent les normes de la société ou du Groupe ONA, que les procédures sont respectées et que les informations utiles sont enregistrées. Veille aux détails des projets ainsi qu'à leur état d'avancement.$$, $$Encourage les membres d'une équipe à s'assurer mutuellement de la qualité de leur travail. Fait valider ses conclusions devant un groupe de travail avant de les considérer comme acquises. Met en place des processus améliorant la qualité et la fiabilité de ses travaux ainsi que ceux de ses collaborateurs.$$, $$Se sent personnellement responsable de la qualité dans tous ses aspects : prestations, coûts, délais, et climat de travail. Dirige des actions de conception et de mise en place de systèmes visant à accroître la fiabilité et la qualité des informations reçues et des résultats produits.$$]::text[])
)
INSERT INTO skills (name, category, description, levels)
SELECT d.name, 'soft_skills', d.description, d.levels
FROM d
WHERE NOT EXISTS (SELECT 1 FROM skills s WHERE lower(trim(s.name)) = lower(trim(d.name)));
